void mainImage( out vec4 O, vec2 u )
{
    float t = iTime * 0.25; // Scaled time for simulation
    vec2 R = iResolution.xy, 
         p = ( u - .5*R ) / R.y, // No panning, removed + t
         n = R-R, N=n, q,c; 
    mat2 m = mat2(cos(vec4(1,12,34,1)));

    for(float S = 10.,j=0.; j++ < 30.; S *= 1.2  )
        p *= m, n *= m,
        n += sin( q = p*S + j + n + t ), 
        N += cos(q)/S;

    O = vec4(1,1,1,0) * (N.x+N.y+.15)*0.15 + .0005/length(N) ;
}
